const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const catalog = [
  { id: 'shirt', name: '오버사이즈 셔츠' },
  { id: 'vest', name: '니트 베스트' },
];

const Cart = () => {
  const [items, setItems] = useState([]);

  const add = (product) => {
    setItems([...items, { id: product.id, name: product.name, qty: 1 }]);
  };

  const remove = (id) => {
    setItems(items.filter((item) => item.id !== id));
  };

  const bump = (id) => {
    setItems(items.map((item) => (item.id === id ? { ...item, qty: item.qty + 1 } : item)));
  };

  return (
    <div>
      <p className="cart">담은 것 {items.length}종류</p>
      <ul className="list">
        {items.map((item) => (
          <li className="item" key={item.id}>
            <span className="item__name">{item.name}</span>
            <span className="item__qty">{item.qty}개</span>
            <button className="bump" type="button" onClick={() => bump(item.id)}>+1</button>
            <button className="remove" type="button" onClick={() => remove(item.id)}>빼기</button>
          </li>
        ))}
      </ul>
      <div className="row">
        {catalog.map((product) => (
          <button className="add" key={product.id} type="button" onClick={() => add(product)}>
            {product.name} 담기
          </button>
        ))}
      </div>
    </div>
  );
};

root.render(<Cart />);

